    uniffiRustCallWithError(V1CryptographicException) { _status ->
    UniffiLib.uniffi_relaysms_spec_payload_fn_method_backuprestore_v1_restore_decrypt(
        it,
        _status)
}
    }
    )
    }
    

    

    


    
