    uniffiRustCallWithError(V1CryptographicException) { _status ->
    UniffiLib.uniffi_relaysms_spec_payload_fn_constructor_backuprestore_v1_backup_encrypt(
    
        FfiConverterByteArray.lower(`data`),_status)
}
    )
    }
    

        
    }
    
